-- The two checklists published on 2026-10-07: running empty at work
-- (Burnout) and a decision that will not land (Decisions).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-07`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-you-have-nothing-left-for-work', 'When You Have Nothing Left for Work', 'For the stretch when the job has emptied you out and pushing harder is no longer working. It helps you find what to put down this week, ask for something concrete, and tell the difference between needing rest and needing a change.', 'Burnout', '["List everything you are carrying at work — depletion is easier to argue with on paper.", "Pick one thing to hand over or let slip this week — nothing changes while the load stays the same.", "Name one concrete thing to ask your manager for — a specific ask is harder to wave away.", "Take the leave you have already earned — unused days help nobody sitting in a system.", "Stop checking messages after a set hour — the day needs an end you can point to.", "Put one thing you enjoy back in the week — the first thing dropped is usually the one that refilled you.", "Say out loud whether rest would fix this — some of it is tiredness and some of it is the job.", "Tell one person outside work how it is going — this gets heavier when nobody else can see it."]'::jsonb, 'weekly', array['Burnout', 'Work']::text[], 1, '2026-10-07T16:00:00+00:00'::timestamptz),
  ('when-you-cannot-make-the-decision', 'When You Cannot Make the Decision', 'For the choice you have been turning over for weeks without landing anywhere. It helps you work out what you are actually weighing, set yourself a deadline, and make the call without needing certainty you are never going to get.', 'Decisions', '["Write the decision as one plain question — half the stall is not knowing what is being asked.", "Give yourself a date to decide by — an open choice takes up room until it has an end.", "Name what you are afraid of either way — fear is usually the thing doing the deciding.", "Write what you would tell a friend in this spot — advice comes out clearer for someone else.", "Ask which option you can undo — a reversible choice needs far less thinking.", "Decide what facts would actually change your mind — otherwise more research is only delay.", "Tell one person which way you are leaning — saying it out loud tends to settle it.", "Make the call and stop reopening it — rehearsing a settled choice costs more than living with it."]'::jsonb, 'as needed', array['Decision Making', 'Worry']::text[], 1, '2026-10-07T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
